class Solution {
  private int[][][][] st;
  private int[] log;

  private int query(int r1, int r2, int c1, int c2) {
    int a = log[r2 - r1 + 1], b = log[c2 - c1 + 1];
    int[][] t = st[a][b];
    return Math.max(
        Math.max(t[r1][c1], t[r2 - (1 << a) + 1][c1]),
        Math.max(t[r1][c2 - (1 << b) + 1], t[r2 - (1 << a) + 1][c2 - (1 << b) + 1]));
  }

  public int countLocalMaximums(int[][] matrix) {
    int n = matrix.length, m = matrix[0].length;
    log = new int[Math.max(n, m) + 2];
    for (int i = 2; i < log.length; i++) log[i] = log[i / 2] + 1;
    int A = log[n] + 1, B = log[m] + 1;
    st = new int[A][B][][];
    st[0][0] = matrix;
    for (int b = 1; b < B; b++) {
      st[0][b] = new int[n][m];
      for (int i = 0; i < n; i++)
        for (int j = 0; j + (1 << b) <= m; j++)
          st[0][b][i][j] = Math.max(st[0][b - 1][i][j], st[0][b - 1][i][j + (1 << (b - 1))]);
    }
    for (int a = 1; a < A; a++) {
      for (int b = 0; b < B; b++) {
        st[a][b] = new int[n][m];
        for (int i = 0; i + (1 << a) <= n; i++)
          for (int j = 0; j + (1 << b) <= m; j++)
            st[a][b][i][j] = Math.max(st[a - 1][b][i][j], st[a - 1][b][i + (1 << (a - 1))][j]);
      }
    }
    int count = 0;
    for (int i = 0; i < n; i++) {
      for (int j = 0; j < m; j++) {
        int x = matrix[i][j];
        if (x == 0) continue;
        int top = Math.max(0, i - x),
            bottom = Math.min(n - 1, i + x),
            left = Math.max(0, j - x),
            right = Math.min(m - 1, j + x);
        int best = 0;
        // rows within x - 1, columns within x
        int r1 = Math.max(0, i - x + 1), r2 = Math.min(n - 1, i + x - 1);
        if (r1 <= r2) best = Math.max(best, query(r1, r2, left, right));
        // rows within x, columns within x - 1
        int c1 = Math.max(0, j - x + 1), c2 = Math.min(m - 1, j + x - 1);
        if (c1 <= c2) best = Math.max(best, query(top, bottom, c1, c2));
        if (best <= x) count++;
      }
    }
    return count;
  }
}
